#include <iostream>
#include <string>

int main() {
    // 1. Default constructor
    std::string s1;

    // 2. Direct constructor with literal
    std::string s2("Welcome to C++");

    // 3. From a C-string array
    char rawText[] = "Good morning";
    std::string s3(rawText);

    // 4. Modern uniform initialization (C++17)
    std::string s4{"Object-Oriented Thinking"};

    std::cout << "s1 is empty: " << std::boolalpha << s1.empty() << "\n";
    std::cout << "s2: " << s2 << "\n";
    std::cout << "s3: " << s3 << "\n";
    std::cout << "s4: " << s4 << "\n";

    return 0;
}

#include <iostream>
#include <string>

int main() {
    // 1. Initial creation and inspections
    std::string s("Welcome");
    std::cout << "Initial: " << s << " (size: " << s.size() << ")\n";

    // 2. append operations
    s.append(" to C++");
    std::cout << "After append: " << s << "\n";
    s.append(3, '!');
    std::cout << "After append chars: " << s << "\n";

    // 3. assign substring
    s.assign("Dallas, Texas", 0, 6);
    std::cout << "After assign: " << s << "\n";

    // 4. at access and erase
    std::cout << "Char at index 1: " << s.at(1) << "\n";
    s.erase(1, 2); // Removes 2 characters starting at index 1
    std::cout << "After erase: " << s << " (size: " << s.size() << ")\n";

    // 5. C-string bridge and empty/clear
    const char* rawPtr = s.c_str();
    std::cout << "c_str output: " << rawPtr << "\n";

    s.clear();
    std::cout << "After clear: size = " << s.size() 
              << ", empty = " << std::boolalpha << s.empty() << "\n";

    return 0;
}
